#include <stdio.h>
#define M 10
int main(void){int a[M][M],b[M][M],c[M][M]={0},r1,c1,r2,c2;if(scanf("%d%d%d%d",&r1,&c1,&r2,&c2)!=4||r1<1||r1>M||c1<1||c1>M||r2<1||r2>M||c2<1||c2>M||c1!=r2){puts("Invalid dimensions");return 1;}for(int i=0;i<r1;i++)for(int j=0;j<c1;j++)if(scanf("%d",&a[i][j])!=1)return 1;for(int i=0;i<r2;i++)for(int j=0;j<c2;j++)if(scanf("%d",&b[i][j])!=1)return 1;for(int i=0;i<r1;i++)for(int j=0;j<c2;j++)for(int k=0;k<c1;k++)c[i][j]+=a[i][k]*b[k][j];for(int i=0;i<r1;i++){for(int j=0;j<c2;j++)printf("%d ",c[i][j]);puts("");}return 0;}